270	template <typename OutputIterator>
271	void extractPeer(const ValueBase* peerData, int family, OutputIterator dest)
272	{
273	  class PeerListValueBaseVisitor : public ValueBaseVisitor {
274	  private:
275	    OutputIterator dest_;
276	    int family_;
277	
278	  public:
279	    PeerListValueBaseVisitor(OutputIterator dest, int family)
280	        : dest_(dest), family_(family)
281	    {
282	    }
283	
284	    virtual ~PeerListValueBaseVisitor() = default;
285	
286	    virtual void visit(const String& peerData) CXX11_OVERRIDE
287	    {
288	      int unit = family_ == AF_INET ? 6 : 18;
289	      size_t length = peerData.s().size();
290	      if (length % unit == 0) {
291	        const unsigned char* base =
292	            reinterpret_cast<const unsigned char*>(peerData.s().data());
293	        const unsigned char* end = base + length;
294	        for (; base != end; base += unit) {
295	          std::pair<std::string, uint16_t> p = unpackcompact(base, family_);
296	          if (p.first.empty()) {
297	            continue;
298	          }
299	          *dest_++ = std::make_shared<Peer>(p.first, p.second);
300	        }
301	      }
302	    }
303	
304	    virtual void visit(const Integer& v) CXX11_OVERRIDE {}
305	    virtual void visit(const Bool& v) CXX11_OVERRIDE {}
306	    virtual void visit(const Null& v) CXX11_OVERRIDE {}
307	
308	    virtual void visit(const List& peerData) CXX11_OVERRIDE
309	    {
310	      for (auto& elem : peerData) {
311	        const Dict* peerDict = downcast<Dict>(elem);
312	        if (!peerDict) {
313	          continue;
314	        }
315	        static const std::string IP = "ip";
316	        static const std::string PORT = "port";
317	        const String* ip = downcast<String>(peerDict->get(IP));
318	        const Integer* port = downcast<Integer>(peerDict->get(PORT));
319	        if (!ip || !port || !(0 < port->i() && port->i() < 65536)) {
320	          continue;
321	        }
322	        *dest_ = std::make_shared<Peer>(ip->s(), port->i());
323	        ++dest_;
324	      }
325	    }
326	
327	    virtual void visit(const Dict& v) CXX11_OVERRIDE {}
328	  };
329	  if (peerData) {
330	    PeerListValueBaseVisitor visitor(dest, family);
331	    peerData->accept(visitor);
332	  }
333	}
