340	// Writes the detailed information about torrent loaded in dctx.
341	template <typename Output>
342	void print(Output& o, const std::shared_ptr<DownloadContext>& dctx)
343	{
344	  TorrentAttribute* torrentAttrs = getTorrentAttrs(dctx);
345	  o.write("*** BitTorrent File Information ***\n");
346	  if (!torrentAttrs->comment.empty()) {
347	    o.printf("Comment: %s\n", torrentAttrs->comment.c_str());
348	  }
349	  if (torrentAttrs->creationDate) {
350	    o.printf("Creation Date: %s\n",
351	             Time(torrentAttrs->creationDate).toHTTPDate().c_str());
352	  }
353	  if (!torrentAttrs->createdBy.empty()) {
354	    o.printf("Created By: %s\n", torrentAttrs->createdBy.c_str());
355	  }
356	  o.printf("Mode: %s\n", getModeString(torrentAttrs->mode));
357	  o.write("Announce:\n");
358	  for (std::vector<std::vector<std::string>>::const_iterator
359	           tierIter = torrentAttrs->announceList.begin(),
360	           eoi = torrentAttrs->announceList.end();
361	       tierIter != eoi; ++tierIter) {
362	    for (auto& elem : *tierIter) {
363	      o.printf(" %s", elem.c_str());
364	    }
365	    o.write("\n");
366	  }
367	  o.printf("Info Hash: %s\n", util::toHex(torrentAttrs->infoHash).c_str());
368	  o.printf("Piece Length: %sB\n",
369	           util::abbrevSize(dctx->getPieceLength()).c_str());
370	  o.printf("The Number of Pieces: %lu\n",
371	           static_cast<unsigned long>(dctx->getNumPieces()));
372	  o.printf("Total Length: %sB (%s)\n",
373	           util::abbrevSize(dctx->getTotalLength()).c_str(),
374	           util::uitos(dctx->getTotalLength(), true).c_str());
375	  if (!torrentAttrs->urlList.empty()) {
376	    o.write("URL List:\n");
377	    for (std::vector<std::string>::const_iterator
378	             i = torrentAttrs->urlList.begin(),
379	             eoi = torrentAttrs->urlList.end();
380	         i != eoi; ++i) {
381	      o.printf(" %s\n", (*i).c_str());
382	    }
383	  }
384	  if (!torrentAttrs->nodes.empty()) {
385	    o.write("Nodes:\n");
386	    for (auto& p : torrentAttrs->nodes) {
387	      o.printf(" %s:%u\n", p.first.c_str(), p.second);
388	    }
389	  }
390	  o.printf("Name: %s\n", torrentAttrs->name.c_str());
391	  o.printf("Magnet URI: %s\n", torrent2Magnet(torrentAttrs).c_str());
392	  util::toStream(dctx->getFileEntries().begin(), dctx->getFileEntries().end(),
393	                 o);
394	}
